/**
 * @module core/errors/boundaryError
 *
 * One error format for every failure at a system boundary (external APIs,
 * database, LLM, Jev, API routes, configuration), so a log line is easy to
 * locate at a glance:
 *
 *   `ErrorName || message || functionName || 🐘`
 *
 * Each boundary has a fixed animal emoji (searchable in logs).
 * Pure functions (scoring, stats) do NOT use this — they just throw plain errors.
 */

/** Fixed emoji per boundary, so you can grep logs by where the error came from. */
export const BOUNDARY_EMOJI = {
  llm: "🦉",
  openMeteo: "🐸",
  fema: "🦡",
  database: "🐘",
  apiRoute: "🦄",
  jev: "🐍",
  config: "🦔",
} as const;

/** Name of a system boundary where errors are caught and wrapped. */
export type Boundary = keyof typeof BOUNDARY_EMOJI;

/** Everything needed to build a {@link BoundaryError}. */
export interface BoundaryErrorOptions {
  /** Short PascalCase error name, e.g. `OpenMeteoFetchError`. */
  name: string;
  /** Human-readable explanation. Must never contain secrets. */
  message: string;
  /** The function in which the error happened, e.g. `fetchDailyWeather`. */
  functionName: string;
  /** Which boundary failed; selects the emoji. */
  boundary: Boundary;
  /** The original error, kept for debugging. */
  cause?: unknown;
}

/**
 * Builds the unified message string `ErrorName || message || functionName || emoji`.
 * @param options - the error parts.
 * @returns the formatted single-line message.
 */
export function formatBoundaryMessage(options: Omit<BoundaryErrorOptions, "cause">): string {
  const emoji = BOUNDARY_EMOJI[options.boundary];
  return `${options.name} || ${options.message} || ${options.functionName} || ${emoji}`;
}

/**
 * Error thrown when something outside our own code fails.
 * Its `message` is already in the unified format.
 */
export class BoundaryError extends Error {
  /** Which boundary failed. */
  readonly boundary: Boundary;
  /** The function in which the error happened. */
  readonly functionName: string;
  /** The plain explanation without the formatting (safe to show users). */
  readonly detail: string;

  /**
   * @param options - error name, message, function name, boundary and optional cause.
   */
  constructor(options: BoundaryErrorOptions) {
    super(formatBoundaryMessage(options), { cause: options.cause });
    this.name = options.name;
    this.boundary = options.boundary;
    this.functionName = options.functionName;
    this.detail = options.message;
  }
}

/**
 * Turns any thrown value into a readable string (errors thrown by libraries
 * are not always `Error` instances).
 * @param error - whatever was thrown.
 * @returns a short description.
 */
export function describeUnknownError(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (typeof error === "string") return error;
  try {
    return JSON.stringify(error);
  } catch {
    return String(error);
  }
}

import { describe, expect, it } from "vitest";
import { BoundaryError, describeUnknownError, formatBoundaryMessage } from "./boundaryError";

describe("formatBoundaryMessage", () => {
  it("builds 'Name || message || function || emoji'", () => {
    expect(
      formatBoundaryMessage({
        name: "SupabaseQueryError",
        message: "relation does not exist",
        functionName: "listActiveHubs",
        boundary: "database",
      }),
    ).toBe("SupabaseQueryError || relation does not exist || listActiveHubs || 🐘");
  });
});

describe("BoundaryError", () => {
  it("keeps name, boundary, function, plain detail and cause", () => {
    const cause = new Error("socket hang up");
    const error = new BoundaryError({
      name: "OpenMeteoFetchError",
      message: "HTTP 429 for hub dallas",
      functionName: "fetchDailyWeather",
      boundary: "openMeteo",
      cause,
    });

    expect(error).toBeInstanceOf(Error);
    expect(error.name).toBe("OpenMeteoFetchError");
    expect(error.message).toBe("OpenMeteoFetchError || HTTP 429 for hub dallas || fetchDailyWeather || 🐸");
    expect(error.detail).toBe("HTTP 429 for hub dallas");
    expect(error.boundary).toBe("openMeteo");
    expect(error.functionName).toBe("fetchDailyWeather");
    expect(error.cause).toBe(cause);
  });
});

describe("describeUnknownError", () => {
  it("handles Error, string and objects", () => {
    expect(describeUnknownError(new Error("boom"))).toBe("boom");
    expect(describeUnknownError("plain")).toBe("plain");
    expect(describeUnknownError({ code: 42 })).toBe('{"code":42}');
  });
});

/**
 * @module core/config/env
 *
 * Reads and validates environment variables with Zod. Each feature has its own
 * getter, so a missing LLM key never breaks, say, the ingest script.
 * Error messages name the missing variables but NEVER print their values.
 */
import { z } from "zod";
import { BoundaryError } from "../errors/boundaryError";

/** Environment variables needed to talk to Supabase (server-side only). */
const supabaseEnvSchema = z.object({
  SUPABASE_URL: z.url(),
  SUPABASE_SECRET_KEY: z.string().min(20),
});

/** Validated Supabase settings. */
export type SupabaseEnv = z.infer<typeof supabaseEnvSchema>;

/**
 * Validates `source` against `schema` and throws a readable config error listing
 * the bad variable names (values are never included).
 * @param schema - Zod schema for the variables.
 * @param source - where to read variables from (defaults to `process.env`).
 * @param functionName - caller name for the error message.
 * @returns the parsed variables.
 */
function parseEnv<T extends z.ZodType>(schema: T, source: NodeJS.ProcessEnv, functionName: string): z.infer<T> {
  const result = schema.safeParse(source);
  if (!result.success) {
    const names = [...new Set(result.error.issues.map((issue) => issue.path.join(".")))].join(", ");
    throw new BoundaryError({
      name: "EnvValidationError",
      message: `Missing or invalid environment variables: ${names}. See .env.example`,
      functionName,
      boundary: "config",
    });
  }
  return result.data;
}

/**
 * Returns validated Supabase settings.
 * @param source - variables to read (defaults to `process.env`; injectable for tests).
 * @returns the Supabase URL and secret key.
 * @throws BoundaryError when a variable is missing or malformed.
 */
export function getSupabaseEnv(source: NodeJS.ProcessEnv = process.env): SupabaseEnv {
  return parseEnv(supabaseEnvSchema, source, "getSupabaseEnv");
}

import { describe, expect, it } from "vitest";
import { getSupabaseEnv } from "./env";

describe("getSupabaseEnv", () => {
  it("returns the variables when valid", () => {
    const env = getSupabaseEnv({
      SUPABASE_URL: "https://example.supabase.co",
      SUPABASE_SECRET_KEY: "[supabase key removed]",
    });
    expect(env.SUPABASE_URL).toBe("https://example.supabase.co");
  });

  it("names missing variables without leaking values", () => {
    const secret = "not-a-url-but-secret-looking";
    expect(() => getSupabaseEnv({ SUPABASE_URL: secret })).toThrowError(
      /EnvValidationError \|\| Missing or invalid environment variables: SUPABASE_URL, SUPABASE_SECRET_KEY/,
    );
    try {
      getSupabaseEnv({ SUPABASE_URL: secret });
    } catch (error) {
      expect(String(error)).not.toContain(secret);
    }
  });
});

