      return `<details><summary>🔧 Tool call: <code>${block.name}</code></summary>\n\n\`\`\`json\n${truncate(
        JSON.stringify(block.input, null, 2),
      )}\n\`\`\`\n</details>`;
    case "tool_result":
      return `<details><summary>📤 Tool result</summary>\n\n\`\`\`\n${truncate(toolResultText(block.content))}\n\`\`\`\n</details>`;
    case "document":
      return `📎 *[Attached document${block.title ? `: ${block.title}` : ""}]*`;
    case "image":
      return "🖼️ *[Attached image]*";
    default:
      return ""; // reasoning blocks and unknown types are not exported
  }
}

/**
 * Renders a list of records as one Markdown document.
 * @param records - parsed transcript records (already scrubbed).
 * @param title - document heading.
 * @returns the Markdown text.
 */
export function renderTranscript(records: TranscriptRecord[], title: string): string {
  const parts = [`# ${title}`, ""];
  for (const record of records.filter(isConversationRecord)) {
    const content = record.message?.content;
    const blocks: ContentBlock[] = typeof content === "string" ? [{ type: "text", text: content }] : (content ?? []);
    const body = blocks.map(renderBlock).filter((text) => text.trim().length > 0).join("\n\n");
    if (!body) continue;
    const onlyToolResults = blocks.every((block) => block.type === "tool_result");
    const heading = record.type === "assistant" ? "🤖 Claude" : onlyToolResults ? "⚙️ Tool output" : "👤 User";
    parts.push(`### ${heading}${record.timestamp ? ` · ${record.timestamp}` : ""}`, "", body, "", "---", "");
  }
  return parts.join("\n");
}

import { describe, expect, it } from "vitest";
import { isConversationRecord, renderTranscript, truncate } from "./render";

describe("isConversationRecord", () => {
  it("keeps main-thread user/assistant records only", () => {
    expect(isConversationRecord({ type: "user", message: { content: "hi" } })).toBe(true);
    expect(isConversationRecord({ type: "assistant", message: { content: [] } })).toBe(true);
    expect(isConversationRecord({ type: "user", isSidechain: true, message: { content: "x" } })).toBe(false);
    expect(isConversationRecord({ type: "summary" })).toBe(false);
  });
});

describe("renderTranscript", () => {
  it("renders text and tool calls, skips reasoning blocks", () => {
    const markdown = renderTranscript(
      [
        { type: "user", timestamp: "t1", message: { content: "Hello" } },
        {
          type: "assistant",
          timestamp: "t2",
          message: {
            content: [
              { type: "thinking", text: "private" },
              { type: "text", text: "Hi there" },
              { type: "tool_use", name: "Bash", input: { command: "ls" } },
            ],
          },
        },
        { type: "user", message: { content: [{ type: "tool_result", content: "file.txt" }] } },
      ],
      "Session",
    );
    expect(markdown).toContain("### 👤 User · t1");
    expect(markdown).toContain("Hi there");
    expect(markdown).toContain("<code>Bash</code>");
    expect(markdown).toContain("### ⚙️ Tool output");
    expect(markdown).not.toContain("private");
  });
});

describe("truncate", () => {
  it("cuts long text and reports the cut", () => {
    const result = truncate("a".repeat(3000));
    expect(result).toContain("[truncated 500 chars]");
  });
});

/**
 * @module scripts/export-session
 *
 * Exports the Claude Code session log(s) into docs/session/ — scrubbed of
 * private details — as required by the assignment ("the full session with the
 * AI agent you worked with").
 *
 * Usage:
 *   npm run session:export -- <path-to-session.jsonl> [more.jsonl ...]
 *   (or set SESSION_LOG_PATHS in .env.local, comma-separated)
 *
 * Output:
 *   docs/session/transcript.md     readable conversation (tool I/O truncated)
 *   docs/session/transcript.jsonl  the scrubbed conversation records, untruncated
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import { buildScrubRules, scrubText } from "./session/scrub";
import { isConversationRecord, renderTranscript, type TranscriptRecord } from "./session/render";

const OUTPUT_DIR = resolve("docs", "session");

/**
 * Reads secret values from .env.local so they are scrubbed even if they were
 * ever pasted into the conversation.
 * @returns the non-empty values.
 */
function readLocalSecretValues(): string[] {
  const envPath = resolve(".env.local");
  if (!existsSync(envPath)) return [];
  return readFileSync(envPath, "utf8")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("#") && line.includes("="))
    .map((line) => line.slice(line.indexOf("=") + 1).trim().replace(/^["']|["']$/g, ""))
    .filter((value) => value.length >= 8);
}

/** Entry point. */
function main(): void {
  const cliPaths = process.argv.slice(2);
  const envPaths = (process.env.SESSION_LOG_PATHS ?? "").split(",").map((p) => p.trim()).filter(Boolean);
  const inputPaths = cliPaths.length > 0 ? cliPaths : envPaths;
  if (inputPaths.length === 0) {
    console.error("Usage: npm run session:export -- <session.jsonl> [more.jsonl ...]");
    process.exit(1);
  }

  const rules = buildScrubRules({ homeDir: homedir(), secretValues: readLocalSecretValues() });
  const keptLines: string[] = [];

  for (const inputPath of inputPaths) {
    const lines = readFileSync(inputPath, "utf8").split(/\r?\n/).filter(Boolean);
    for (const line of lines) {
      const record = JSON.parse(line) as TranscriptRecord;
      if (isConversationRecord(record)) keptLines.push(scrubText(line, rules));
    }
  }

  const records = keptLines.map((line) => JSON.parse(line) as TranscriptRecord);
  mkdirSync(OUTPUT_DIR, { recursive: true });
  writeFileSync(join(OUTPUT_DIR, "transcript.jsonl"), `${keptLines.join("\n")}\n`);
  writeFileSync(
    join(OUTPUT_DIR, "transcript.md"),
    renderTranscript(records, "The Daily Prophet — full AI coding session (scrubbed)"),
  );
  console.log(`✅ Exported ${records.length} records from ${inputPaths.length} file(s) to ${OUTPUT_DIR}`);
}

main();

